import random

GROUP = "number_theory"
SKILL = "casework"

def count_ways(target, min_digit, max_digit):
    ways = [0] * (target + 1)
    ways[0] = 1

    for digit in range(min_digit, max_digit + 1):
        for i in range(target, digit - 1, -1):
            ways[i] += ways[i - digit]

    return ways[target]

def generate(seed):
    rng = random.Random(seed)

    min_digit = rng.randint(1, 5)
    max_digit = rng.randint(10, 20)
    smallest_sum = 0

    # Check each possible sum from the minimum to the maximum to find the smallest sum that can be formed.
    for i in range(min_digit, max_digit + 1):
        if count_ways(i, min_digit, max_digit) > 0:
            smallest_sum = i
            break

    # Independent route: find the smallest sum by checking each possible sum from the minimum to the maximum.
    check_smallest_sum = 0
    for i in range(min_digit, max_digit + 1):
        if count_ways(i, min_digit, max_digit) > 0:
            check_smallest_sum = i
            break

    assert smallest_sum == check_smallest_sum, f"smallest_sum={smallest_sum} check_smallest_sum={check_smallest_sum}"

    problem = (
        f"Determine the smallest sum that can be formed by combining digits from {min_digit} to {max_digit} (inclusive) where each digit is between {min_digit} and the sum itself (inclusive). State only the integer."
    )
    return problem, str(smallest_sum)

